Here’s a **complete Linked List program in C** that works with **strings instead of numbers** and includes **all the main functions** (insert, delete, display, search, concatenate, etc.).  

---

### ✅ **Full Code: Linked List of Strings (C)**

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct Node {
    char data[100];
    struct Node* next;
};

// Function to create a new node
struct Node* createNode(char value[]) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    strcpy(newNode->data, value);
    newNode->next = NULL;
    return newNode;
}

// Insert at beginning
void insertAtBeginning(struct Node** head, char value[]) {
    struct Node* newNode = createNode(value);
    newNode->next = *head;
    *head = newNode;
}

// Insert at end
void insertAtEnd(struct Node** head, char value[]) {
    struct Node* newNode = createNode(value);
    if (*head == NULL) {
        *head = newNode;
        return;
    }
    struct Node* temp = *head;
    while (temp->next != NULL)
        temp = temp->next;
    temp->next = newNode;
}

// Display list
void display(struct Node* head) {
    if (head == NULL) {
        printf("List is empty.\n");
        return;
    }
    while (head != NULL) {
        printf("%s -> ", head->data);
        head = head->next;
    }
    printf("NULL\n");
}

// Search for a string
void search(struct Node* head, char key[]) {
    while (head != NULL) {
        if (strcmp(head->data, key) == 0) {
            printf("'%s' found in list.\n", key);
            return;
        }
        head = head->next;
    }
    printf("'%s' not found.\n", key);
}

// Delete a node by value
void deleteNode(struct Node** head, char key[]) {
    struct Node* temp = *head;
    struct Node* prev = NULL;

    if (temp != NULL && strcmp(temp->data, key) == 0) {
        *head = temp->next;
        free(temp);
        return;
    }

    while (temp != NULL && strcmp(temp->data, key) != 0) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) {
        printf("'%s' not found.\n", key);
        return;
    }

    prev->next = temp->next;
    free(temp);
}

// Concatenate two linked lists
void concatenate(struct Node** head1, struct Node* head2) {
    if (*head1 == NULL) {
        *head1 = head2;
        return;
    }
    struct Node* temp = *head1;
    while (temp->next != NULL)
        temp = temp->next;
    temp->next = head2;
}

// Free entire list
void freeList(struct Node** head) {
    struct Node* temp;
    while (*head != NULL) {
        temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}

int main() {
    struct Node* list1 = NULL;
    struct Node* list2 = NULL;

    // Insert some strings into list1
    insertAtEnd(&list1, "Apple");
    insertAtEnd(&list1, "Banana");
    insertAtEnd(&list1, "Cherry");

    printf("List 1:\n");
    display(list1);

    // Insert some strings into list2
    insertAtEnd(&list2, "Mango");
    insertAtEnd(&list2, "Orange");

    printf("\nList 2:\n");
    display(list2);

    // Concatenate
    printf("\nAfter concatenation:\n");
    concatenate(&list1, list2);
    display(list1);

    // Search and Delete examples
    search(list1, "Banana");
    deleteNode(&list1, "Banana");

    printf("\nAfter deleting 'Banana':\n");
    display(list1);

    // Free memory
    freeList(&list1);
    freeList(&list2);

    return 0;
}
```

---

### 🧠 What it covers:
- Create a linked list that stores **strings**  
- Add nodes at **beginning** and **end**  
- **Display** the list  
- **Search** a string  
- **Delete** a node by string  
- **Concatenate** two lists  
- **Free** all memory safely  

